159	type headerTransport struct {
160		headers http.Header
161		base    http.RoundTripper
162	}
163	
164	func (t *headerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
165		rt := t.base
166		newReq := *req
167		newReq.Header = make(http.Header)
168		for k, vv := range req.Header {
169			newReq.Header[k] = vv
170		}
171	
172		for k, v := range t.headers {
173			newReq.Header[k] = v
174		}
175	
176		return rt.RoundTrip(&newReq)
177	}
