461	func addOpenTelemetryStatsHandler(dialOpts []grpc.DialOption, opts *Options, endpoint string) []grpc.DialOption {
462		if opts.DisableTelemetry {
463			return dialOpts
464		}
465		if gax.IsFeatureEnabled("METRICS") {
466			host, port := extractHostPort(endpoint)
467			dialOpts = append(dialOpts, grpc.WithChainUnaryInterceptor(openTelemetryUnaryClientInterceptor(host, port)))
468		}
469		if !gax.IsFeatureEnabled("TRACING") && !gax.IsFeatureEnabled("LOGGING") {
470			return append(dialOpts, grpc.WithStatsHandler(otelgrpc.NewClientHandler()))
471		}
472		var staticAttrs []attribute.KeyValue
473		var scopedLogger *slog.Logger
474		if opts.InternalOptions != nil {
475			staticAttrs = transport.StaticTelemetryAttributes(opts.InternalOptions.TelemetryAttributes)
476			if gax.IsFeatureEnabled("LOGGING") && opts.Logger != nil {
477				var staticLogAttrs []any
478				for _, attr := range staticAttrs {
479					staticLogAttrs = append(staticLogAttrs, slog.String(string(attr.Key), attr.Value.AsString()))
480				}
481				scopedLogger = opts.Logger.With(staticLogAttrs...)
482			}
483		}
484		var otelOpts []otelgrpc.Option
485		if gax.IsFeatureEnabled("TRACING") {
486			otelOpts = append(otelOpts, otelgrpc.WithSpanAttributes(staticAttrs...))
487		}
488		return append(dialOpts, grpc.WithStatsHandler(&otelHandler{
489			Handler: otelgrpc.NewClientHandler(otelOpts...),
490			logger:  scopedLogger,
491		}))
492	}
