514	// openTelemetryUnaryClientInterceptor returns an interceptor that populates
515	// TransportTelemetryData with the server peer address.
516	func openTelemetryUnaryClientInterceptor(host string, port int) grpc.UnaryClientInterceptor {
517		return func(ctx context.Context, method string, req, reply any, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
518			transportData := gax.ExtractTransportTelemetry(ctx)
519			if transportData != nil {
520				if host != "" {
521					transportData.SetServerAddress(host)
522				}
523				if port != 0 {
524					transportData.SetServerPort(port)
525				}
526			}
527	
528			err := invoker(ctx, method, req, reply, cc, opts...)
529	
530			return err
531		}
532	}
