534	// otelHandler is a wrapper around the OpenTelemetry gRPC client handler that
535	// adds custom Google Cloud-specific attributes to spans and metrics.
536	type otelHandler struct {
537		stats.Handler
538		logger *slog.Logger
539	}
540	
541	// TagRPC intercepts the RPC start to extract dynamic attributes like resource
542	// name and retry count from the outgoing context metadata and attach them to
543	// the current span.
544	func (h *otelHandler) TagRPC(ctx context.Context, info *stats.RPCTagInfo) context.Context {
545		ctx = h.Handler.TagRPC(ctx, info)
546	
547		var span trace.Span
548		if gax.IsFeatureEnabled("TRACING") {
549			if s := trace.SpanFromContext(ctx); s != nil && s.IsRecording() {
550				span = s
551			}
552		}
553	
554		if span == nil {
555			return ctx
556		}
557		var attrs []attribute.KeyValue
558		if resName, ok := callctx.TelemetryFromContext(ctx, "resource_name"); ok {
559			attrs = append(attrs, attribute.String("gcp.resource.destination.id", resName))
560		}
561		if resendCountStr, ok := callctx.TelemetryFromContext(ctx, "resend_count"); ok {
562			if count, err := strconv.Atoi(resendCountStr); err == nil {
563				attrs = append(attrs, attribute.Int("gcp.grpc.resend_count", count))
564			}
565		}
566		if len(attrs) > 0 {
567			span.SetAttributes(attrs...)
568		}
569		return ctx
570	}
