572	// HandleRPC intercepts the RPC completion to capture and format error-related
573	// attributes ensuring they conform to Google Cloud observability standards.
574	func (h *otelHandler) HandleRPC(ctx context.Context, s stats.RPCStats) {
575		end, ok := s.(*stats.End)
576		if !ok {
577			h.Handler.HandleRPC(ctx, s)
578			return
579		}
580	
581		var span trace.Span
582		if gax.IsFeatureEnabled("TRACING") {
583			if s := trace.SpanFromContext(ctx); s != nil && s.IsRecording() {
584				span = s
585			}
586		}
587	
588		var logger *slog.Logger
589		if gax.IsFeatureEnabled("LOGGING") {
590			if l := h.logger; l != nil && l.Enabled(ctx, slog.LevelDebug) {
591				logger = l
592			}
593		}
594	
595		if span == nil && logger == nil {
596			h.Handler.HandleRPC(ctx, s)
597			return
598		}
599	
600		if end.Error != nil {
601			h.handleRPCError(ctx, span, logger, end)
602		} else {
603			h.handleRPCSuccess(span)
604		}
605		h.Handler.HandleRPC(ctx, s)
606	}
